class Range {
  constructor(start, end, step = 1) {
    this.start = start; this.end = end; this.step = step;
  }
  [Symbol.iterator]() {
    let cur = this.start;
    const { end, step } = this;
    return {
      next: () => {
        if (cur > end) return { value: undefined, done: true };
        const value = cur;
        cur += step;
        return { value, done: false };
      },
    };
  }
}
console.log([...new Range(1, 10, 3)].join(","));
let sum = 0;
for (const n of new Range(1, 5)) sum += n;
