async function retry(fn, { retries = 3, delay = 5 } = {}) {
  let lastError;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await fn(attempt);
    } catch (err) {
      lastError = err;
      if (attempt < retries) {
        await new Promise((r) => setTimeout(r, delay * 2 ** attempt));
      }
    }
  }
  throw lastError;
}
